"""Tests for the :mod:`roman` module.

The worker that owns this module will make these tests pass by
implementing the conversion functions.
"""

import unittest

from roman import to_roman, from_roman


class TestRoman(unittest.TestCase):
    def test_to_roman(self):
        self.assertEqual(to_roman(1994), "MCMXCIV")

    def test_from_roman(self):
        self.assertEqual(from_roman("MMXXI"), 2021)


if __name__ == "__main__":
    unittest.main()
